-- V114 — Aria v2: stamp the 35 workflow step-pages referenced by transitions
-- but missing from page_definition (6 workflows: EwayBill, Appraisal, Hiring,
-- IncrementLetter, PlantTransfer, ReturnMaterial). Each is an inbox list filtered
-- to the transition's from-state with a rowAction advancing to the to-state
-- (the proven pico:si-finalize pattern); entities without a status column get a
-- plain list. Idempotent (guarded by page code). Pure substrate data.

-- pico:eway-create  (M10.EwayBill: DRAFT -> SUBMITTED)
INSERT INTO page_definition (tenant_id, code, title, description, category, status, created_at, updated_at) SELECT 1,'pico:eway-create','Eway Create','Workflow step (M10.EwayBill): advance DRAFT -> SUBMITTED.','M10','PUBLISHED',NOW(),NOW() WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE code='pico:eway-create');
INSERT INTO page_version (page_id, version, status, body_json, created_at) SELECT pd.id,1,'PUBLISHED','{"kind":"list","title":"Eway Create","dataSource":{"type":"entity","entity":"EwayBill","filter":{"field":"current_step","op":"eq","value":"DRAFT"}},"columns":[{"field":"id","label":"#","sortable":true},{"field":"current_step","label":"State","sortable":true,"render":"badge"}],"rowActions":[{"label":"Submitted","action":"entity.update-field","args":{"field":"current_step","value":"SUBMITTED"},"color":"secondary"}],"pageSize":25}',NOW() FROM page_definition pd WHERE pd.code='pico:eway-create' AND NOT EXISTS (SELECT 1 FROM page_version pv WHERE pv.page_id=pd.id);
UPDATE page_definition pd JOIN page_version pv ON pv.page_id=pd.id SET pd.current_version_id=pv.id WHERE pd.code='pico:eway-create' AND pd.current_version_id IS NULL;
